using SystemWorld;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
public static class FoundationBuilder {
 public static void Prepare(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);var root=new GameObject("WORLD_FOUNDATION bootstrap");root.AddComponent<FoundationBootstrap>();System.IO.Directory.CreateDirectory("Assets/_SYSTEM/Scenes");EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_SYSTEM/Scenes/WORLD_FOUNDATION.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene("Assets/_SYSTEM/Scenes/WORLD_FOUNDATION.unity",true)};PlayerSettings.companyName="SYSTEM Experimental";PlayerSettings.productName="SYSTEM World Foundation TEMP";PlayerSettings.SetApplicationIdentifier(UnityEditor.Build.NamedBuildTarget.Android,"com.system.worldfoundation.spike");PlayerSettings.Android.minSdkVersion=AndroidSdkVersions.AndroidApiLevel31;PlayerSettings.defaultInterfaceOrientation=UIOrientation.LandscapeLeft;AssetDatabase.SaveAssets();}
 public static void ExportAndroid(){Prepare();EditorUserBuildSettings.exportAsGoogleAndroidProject=true;var entry=typeof(PlayerSettings.Android).GetProperty("applicationEntry");if(entry==null)throw new System.Exception("Android Activity entry API missing");entry.SetValue(null,System.Enum.Parse(entry.PropertyType,"Activity"));PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android,ScriptingImplementation.IL2CPP);PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/_SYSTEM/Scenes/WORLD_FOUNDATION.unity"},target=BuildTarget.Android,locationPathName=@"E:\SYSTEM\.tmp\system-world-foundation\unity-export",options=BuildOptions.Development});if(result.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new System.Exception("Android export failed: "+result.summary.result);}
